# ─────────────────────────────────────────────────────────────────────────────
# HELPERS
# ─────────────────────────────────────────────────────────────────────────────
def fmt(x, prefix='', suffix='', decimals=1):
    if x is None or (isinstance(x, float) and np.isnan(x)):
        return '<span style="color:#c0c8d8">N/A</span>'
    if decimals == 0:
        return f"{prefix}{int(round(x)):,}{suffix}"
    return f"{prefix}{x:,.{decimals}f}{suffix}"

def badge(val, thresholds, labels=None):
    if labels is None:
        labels = ['badge-low','badge-mid','badge-high']
    if val >= thresholds[1]:
        return f'<span class="badge {labels[2]}">{val:.1f}%</span>'
    elif val >= thresholds[0]:
        return f'<span class="badge {labels[1]}">{val:.1f}%</span>'
    else:
        return f'<span class="badge {labels[0]}">{val:.1f}%</span>'

def bar_chart(canvas_id, labels, datasets, kind='bar', width=700, height=340,
