    idx_mode = 'index' if horizontal else 'category'
    default_colors = [
        '#4a90d9','#e67e22','#27ae60','#9b59b6','#e74c3c','#1abc9c','#f39c12','#34495e'
    ]
    if colors is None:
        colors = default_colors

    ds = []
    for i, (label, data) in enumerate(datasets):
        c = colors[i % len(colors)]
        ds.append({
            'label': label,
            'data': data,
            'backgroundColor': c + 'cc',
            'borderColor': c,
            'borderWidth': 1.5,
            'borderRadius': 4,
            'borderRadiusTopLeft': 4,
            'borderRadiusTopRight': 4,
        })

    config = {
        'type': chart_type,
        'data': {
            'labels': labels,
            'datasets': ds
        },
        'options': {
            'responsive': True,
            'maintainAspectRatio': True,
            'indexAxis': 'y' if horizontal else 'x',
            'plugins': {
                'legend': {'position': 'top', 'labels': {'font': {'family': 'Inter', 'size': 12},
                    'boxWidth': 12, 'padding': 16}},
                'tooltip': {'backgroundColor': '#0f2040', 'titleFont': {'family': 'Inter'},
                    'bodyFont': {'family': 'Inter'}, 'cornerRadius': 8, 'padding': 10}
            },
            'scales': {
                'x': {'grid': {'color': '#f0f4f8'}, 'ticks': {'font': {'family': 'Inter', 'size': 11},
                    'color': '#6b7a99'}},
                'y': {'grid': {'display': False}, 'ticks': {'font': {'family': 'Inter', 'size': 11},
                    'color': '#3d4a5c'}}
            }
        }
    }
    if stacked:
        config['options']['scales']['x']['stacked'] = True
        config['options']['scales']['y']['stacked'] = True

    html = f"""
  <div class="chart-wrap" style="max-width:{width}px; margin:0 auto;">
    <canvas id="{canvas_id}"></canvas>
  </div>
  <script>
  (function(){{
    var ctx = document.getElementById('{canvas_id}').getContext('2d');
    new Chart(ctx, {json.dumps(config, indent=None)});
  }})();
  </script>"""
    return html

def donut_chart(canvas_id, labels, data, colors, width=300, height=260):
    config = {
        'type': 'doughnut',
        'data': {
            'labels': labels,
            'datasets': [{
                'data': data,
                'backgroundColor': [c + 'cc' for c in colors],
                'borderColor': [c for c in colors],
                'borderWidth': 2
            }]
        },
        'options': {
            'responsive': True,
            'cutout': '62%',
            'plugins': {
                'legend': {'position': 'right', 'labels': {'font': {'family': 'Inter', 'size': 11},
                    'boxWidth': 10, 'padding': 10}},
                'tooltip': {'backgroundColor': '#0f2040', 'titleFont': {'family': 'Inter'},
                    'bodyFont': {'family': 'Inter'}, 'cornerRadius': 8}
            }
        }
    }
    return f"""
  <div class="chart-wrap" style="max-width:{width}px;">
    <canvas id="{canvas_id}"></canvas>
  </div>
  <script>
  (function(){{
    var ctx = document.getElementById('{canvas_id}').getContext('2d');
    new Chart(ctx, {json.dumps(config, indent=None)});
  }})();
